using CallbackFn = int (*)(int);

class TaskRunner {
    static int process(int x) { return x * x; }
public:
    // Conversion Operator: Converts TaskRunner object 
    // to a standard C function pointer type.
    operator CallbackFn() const {
        return &process;
    }
};

// Usage example (Conceptual):
// CallbackFn f = TaskRunner{};
// int result = f(5); // result is 25
// Note: This pattern requires the target function 
// to be static or globally accessible.
